import clsx from 'clsx';
import React from 'react';

import { dataTableV2CellCSS } from './DataTableV2Cell.sty.js';
import type { DataTestId } from '../../../core/types/data-props.js';
import type { StylingProps } from '../../../core/types/styling-props.js';
import type { WithChildren } from '../../../core/types/with-children.js';
import { useDataTableV2 } from '../contexts/DataTableV2Context.js';

// #region Typings
/**
 * @internal
 */
export type DataTableV2DefaultCellProps = WithChildren &
  StylingProps &
  DataTestId;
// #endregion Typings

/**
 * DataTableV2 custom Cell renderer Wrapper.
 *
 * @internal
 *
 * @returns DefaultCell component
 */
export const DataTableV2DefaultCell = (props: DataTableV2DefaultCellProps) => {
  const {
    children,
    style: consumerStyle,
    className: consumerClassName,
    'data-testid': dataTestId,
  } = props;

  const table = useDataTableV2();

  return (
    <div
      className={clsx(
        dataTableV2CellCSS({
          rowDensity: table.getVisualVariantOptions().rowDensity,
          rowSeparation: 'none',
          loading: table.getState().loading,
        }),
        consumerClassName,
      )}
      style={consumerStyle}
      data-testid={dataTestId}
    >
      {children}
    </div>
  );
};
DataTableV2DefaultCell['displayName'] = 'DataTableV2.DefaultCell';
